import { Badge } from '@/components/ui/badge';
import { formatCurrency } from '@/functions/formaters/formatCurrency';
import { ArrowLeft, FileX } from 'lucide-react';
import type { TDueDiligenceDetailedCardItem } from '../../types/dueItem';
import { DocumentPreviewer } from '../shared/DocumentPreviewer';
import { SectionLabel } from './SectionLabel';

export function DetalheCertidoes({
    certidoes,
    onPreview,
    onVoltar
}: {
    certidoes: TDueDiligenceDetailedCardItem['certidoes_data'];
    onVoltar: () => void;
    onPreview?: (doc: { arquivo_url?: string | null; name?: string }) => void;
}) {

    if (!certidoes) return null;

    const certNegativasCount = certidoes.filter(c => c.resultado === 'negativa').length;
    const certPositivasCount = certidoes.filter(c => c.resultado === 'positiva').length;
    const dividaFiscalTotal = certidoes.reduce((acc, cert) => acc + (cert.valor_divida ?? 0), 0);

    return (
        <div className="flex flex-col gap-2">
            <button
                type="button"
                onClick={onVoltar}
                className="mb-4 flex items-center gap-1.5 bg-transparent p-0 text-xs text-subtitle transition-colors hover:text-title"
            >
                <ArrowLeft size={14} />
                Voltar às movimentações
            </button>

            <div className="-mt-3">
                <SectionLabel className="tracking-normal mb-2 text-base">
                    <span className="text-title">Resumo de Certidões</span>
                </SectionLabel>
                <div className="grid grid-cols-2 gap-2">
                    <div className="rounded-md border border-emerald-200 dark:border-emerald-700 bg-emerald-50 dark:bg-emerald-950/60 p-2 text-center">
                        <p className="text-xs font-extrabold text-emerald-500 dark:text-emerald-400">{certNegativasCount}</p>
                        <p className="text-[10px] font-semibold text-emerald-500">NEGATIVAS</p>
                    </div>
                    <div className="rounded-md border border-red-200 dark:border-red-800/70 bg-red-50 dark:bg-red-950/30 text-center">
                        <p className="text-xsfont-extrabold text-red-500">
                            {certPositivasCount}
                        </p>
                        <p className="text-[10px] font-semibold text-red-500">POSITIVAS</p>
                    </div>
                </div>

