interface IHistoricoDocumentPreviewPanelProps {
    nome: string;
    url: string;
    documentType: 'pdf' | 'img';
    onClose: () => void;
}

export function HistoricoDocumentPreviewPanel({
    nome,
    url,
    documentType,
    onClose,
}: IHistoricoDocumentPreviewPanelProps) {
    const resolvedType = documentType || (isPdfFileName(nome) ? 'pdf' : 'img');

    return (
        <div className="flex h-full min-h-0 flex-col border-l border-celer-line">
            <div className="flex shrink-0 items-center justify-between gap-3 border-b border-celer-line px-4 py-3">
                <div className="min-w-0">
                    <p className="m-0 truncate font-satoshi text-sm font-semibold text-foreground">
                        {nome}
                    </p>
                    <p className="m-0 text-[0.7rem] text-muted-foreground">Preview do documento</p>
                </div>
                <button
                    type="button"
                    onClick={onClose}
                    aria-label="Fechar preview do documento"
                    className="flex size-8 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-black/5 hover:text-foreground dark:hover:bg-white/5"
                >
                    <X size={16} aria-hidden />
                </button>
            </div>
            <div className="min-h-0 flex-1 overflow-auto bg-celer-panel/30 p-3">
                <DocumentPreviewer url={url} documentType={resolvedType} pageWidth={70} />
            </div>
        </div>
    );
}

