export function HistoricoDetailPanel({
    pendencia,
    currDocs,
    isDocsLoading,
    previewDocumentId,
    onOpenDocumentPreview,
    onClearSelection,
}: IHistoricoDetailPanelProps) {
    const categoriaMeta = getCategoriaById([], pendencia.categoria);
    const categoriaLabel = resolvePendenciaCategoriaLabel(
        pendencia.categoria,
        categoriaMeta?.label,
    );
    const categoriaColor = categoriaMeta?.color ?? catColor(categoriaLabel);

    return (
        <div className="flex h-full min-h-0 flex-col border-l border-celer-line">
            <div className="flex shrink-0 items-start justify-between gap-3 border-b border-celer-line px-4 py-4">
                <div className="min-w-0">
                    <div className="mb-2 flex flex-wrap gap-1">
                        <span
                            className="inline-block rounded-full px-2 py-0.5 text-[0.65rem] font-semibold"
                            style={{
                                background: `${categoriaColor}15`,
                                color: categoriaColor,
                            }}
                        >
                            {categoriaLabel}
                        </span>
                        {pendencia.impedimento ? (
                            <span className="inline-flex items-center gap-1 rounded-full bg-red-500/15 px-2 py-0.5 text-[0.65rem] font-bold text-red-500">
                                <AlertTriangle size={10} aria-hidden /> Impeditiva
                            </span>
                        ) : null}
                    </div>
                    <h4 className="m-0 wrap-break-word font-satoshi text-sm font-semibold text-foreground">
                        {pendencia.titulo}
                    </h4>
                    <div className="mt-2 flex flex-wrap items-center gap-3">
                        {pendencia.registrado_por ? (
                            <span className="inline-flex items-center gap-1 text-[0.7rem] text-muted-foreground">
                                <User size={12} aria-hidden /> {pendencia.registrado_por}
                            </span>
                        ) : null}
                        {pendencia.data_registro ? (
                            <span className="inline-flex items-center gap-1 text-[0.7rem] text-muted-foreground">
                                <Clock size={12} aria-hidden />{' '}
                                {formatDataPend(pendencia.data_registro)} · há{' '}
                                {tempoDecorrido(pendencia.data_registro)}
                            </span>
                        ) : null}
                    </div>
                </div>
                <button
                    type="button"
                    onClick={onClearSelection}
                    aria-label="Voltar para a listagem"
                    className="flex size-8 shrink-0 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-black/5 hover:text-foreground dark:hover:bg-white/5"
                >
                    <X size={16} aria-hidden />
                </button>
            </div>

            <div className="min-h-0 flex-1 space-y-5 overflow-y-auto p-4">
                <div>
                    <SectionLabel>EXPLICAÇÃO DA PENDÊNCIA</SectionLabel>
                    <p className="m-0 text-[0.78rem] leading-[1.8] text-muted-foreground">
                        {pendencia.descricao || 'Sem descrição registrada.'}
                    </p>
                </div>

                {pendencia.video_url ? (
                    <div>
                        <SectionLabel>VÍDEO TUTORIAL</SectionLabel>
                        <a
                            href={pendencia.video_url}
                            target="_blank"
                            rel="noopener noreferrer"
                            className="inline-flex items-center gap-1.5 text-[0.78rem] font-medium text-celer-blue no-underline hover:underline"
                        >
                            Abrir vídeo
                            <ExternalLink size={14} aria-hidden />
                        </a>
                    </div>
                ) : null}

                <div>
                    <SectionLabel>
                        DOCUMENTOS ({currDocs.length})
                        {isDocsLoading ? ' · carregando…' : ''}
                    </SectionLabel>
                    {isDocsLoading && currDocs.length === 0 ? (
                        <div className="flex items-center gap-2 text-[0.72rem] text-muted-foreground">
                            <Loader2 size={12} className="animate-spin" aria-hidden />
                            Carregando documentos…
                        </div>
                    ) : null}
                    {currDocs.length === 0 && !isDocsLoading ? (
                        <p className="mb-2 text-[0.72rem] text-muted-foreground">
                            Nenhum documento anexado.
                        </p>
                    ) : null}
                    {currDocs.map((doc) => {
                        const previewUrl = resolveDocPreviewUrl(doc);
                        const isPreviewActive = previewDocumentId === doc.id;

                        return (
                            <div
                                key={doc.id}
                                className="mb-1.5 flex items-center gap-2.5 rounded-lg border border-celer-line bg-celer-panel/40 px-3 py-2"
                            >
                                <FileText size={14} className="shrink-0 text-amber-500" aria-hidden />
                                <div className="min-w-0 flex-1">
                                    <span className="block truncate text-[0.75rem] font-semibold text-foreground">
                                        {doc.nome}
                                    </span>
                                </div>
                                {previewUrl ? (
                                    <button
                                        type="button"
                                        onClick={() =>
                                            onOpenDocumentPreview({
                                                ...doc,
                                                url: previewUrl,
                                            })
                                        }
                                        aria-label={`Visualizar ${doc.nome}`}
                                        className={
                                            isPreviewActive
                                                ? 'flex size-8 items-center justify-center rounded-lg bg-celer-blue/15 text-celer-blue'
                                                : 'flex size-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-celer-blue/10 hover:text-celer-blue'
                                        }
                                    >
                                        <Eye size={12} aria-hidden />
                                    </button>
                                ) : null}
                                {previewUrl ? (
                                    <a
                                        href={previewUrl}
                                        target="_blank"
                                        rel="noopener noreferrer"
                                        aria-label={`Baixar ${doc.nome}`}
                                        className="flex size-8 items-center justify-center rounded-lg text-muted-foreground no-underline transition-colors hover:bg-emerald-500/10 hover:text-emerald-500"
                                    >
                                        <Download size={12} aria-hidden />
                                    </a>
                                ) : null}
                            </div>
                        );
                    })}
                </div>

                {(pendencia.tentativas_anteriores?.length ?? 0) > 0 ? (
                    <TentativasAnteriores tentativas={pendencia.tentativas_anteriores} />
                ) : null}
            </div>
        </div>
    );
}

